import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"Orrery diagram art — the \\"sketched Wired\\" style","description":"","frontmatter":{},"headers":[],"relativePath":"guides/diagram-art-style.md","filePath":"guides/diagram-art-style.md"}'),o={name:"guides/diagram-art-style.md"};function i(n,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="orrery-diagram-art-—-the-sketched-wired-style" tabindex="-1">Orrery diagram art — the &quot;sketched Wired&quot; style <a class="header-anchor" href="#orrery-diagram-art-—-the-sketched-wired-style" aria-label="Permalink to &quot;Orrery diagram art — the &quot;sketched Wired&quot; style&quot;">​</a></h1><p>The house style for editorial diagrams across Orrery — <strong>The Long View essays</strong> now, and the <strong>/science</strong> section later (same pipeline, same look, so the whole atlas reads as one hand). Locked with Marko, July 2026.</p><p>Reference implementations: the <a href="./../wip/the-long-view-navigation-prototype">Navigation essay</a> (first pass) and <strong>delta-v</strong> (first pass in this style). The sources live under <code>docs/wip/essay-diagram-sources/&lt;slug&gt;/*.svg</code>.</p><hr><h2 id="the-pipeline-svg-sketch-→-higgsfield-art" tabindex="-1">The pipeline (SVG sketch → Higgsfield art) <a class="header-anchor" href="#the-pipeline-svg-sketch-→-higgsfield-art" aria-label="Permalink to &quot;The pipeline (SVG sketch → Higgsfield art)&quot;">​</a></h2><ol><li><strong>Author a precise SVG sketch</strong> — the compositional + factual truth. Deterministic, in-palette, every label + number in place. Build script pattern: <code>scripts/essays/build-&lt;slug&gt;-sketches.mjs</code> (mirror <code>build-nav-diagram-sketches.mjs</code>). Rasterise each to a 2048-px PNG with <code>sharp</code>. Output to <code>docs/wip/essay-diagram-sources/&lt;slug&gt;/</code> (NOT the shipped <code>static/</code> tree).</li><li><strong>Upload each PNG to Higgsfield</strong> (<code>media_upload</code> → PUT the presigned URL → <code>media_confirm</code>).</li><li><strong>Generate</strong> with <code>nano_banana_pro</code>, <code>aspect_ratio: &quot;16:9&quot;</code>, <code>resolution: &quot;2k&quot;</code>, passing the sketch as <code>medias: [{ value: &lt;media_id&gt;, role: &quot;image&quot; }]</code> and the <strong>style prompt below</strong> (swap in the per-diagram subject + labels).</li><li><strong>Download the raw art</strong>, convert to <code>static/images/essays/&lt;slug&gt;/&lt;name&gt;.webp</code> (<code>sharp().resize(1600).webp({ quality: 86 })</code>).</li><li><strong>Wire</strong> the <code>figure</code> blocks into the essay overlay + set <code>hero</code> in the base (see <code>scripts/essays/wire-nav-figures.mjs</code>). <code>align: &#39;wide&#39;</code>.</li></ol><h2 id="the-palette" tabindex="-1">The palette <a class="header-anchor" href="#the-palette" aria-label="Permalink to &quot;The palette&quot;">​</a></h2><p>Deep midnight-navy ground <code>#0a0e18</code> · luminous cyan linework <code>#7fb0e0</code> · warm-cream highlights <code>#cfe3fb</code>/white · a single warm-amber glow <code>#ffd27f</code> for a Sun/star/key accent. Faint blueprint grid + printed-paper grain ghosted behind. Monospace/hand lettering.</p><h2 id="the-locked-style-prompt-the-blend" tabindex="-1">The locked style prompt (the &quot;blend&quot;) <a class="header-anchor" href="#the-locked-style-prompt-the-blend" aria-label="Permalink to &quot;The locked style prompt (the &quot;blend&quot;)&quot;">​</a></h2><p>A blend of <em>elegant hand-sketched</em> (spare, atmospheric, glowing amber accent) and <em>engineering-notebook</em> (ghosted blueprint grid, hand-lettered callouts). Use verbatim, substituting the bracketed parts:</p><blockquote><p>Reinterpret this schematic as a hand-drawn editorial feature illustration for WIRED magazine — art-directed, not a clean computer diagram. Elegant, confident hand-sketched ink linework with light cross-hatching and a few loose construction strokes; hand-lettered annotations that feel drawn, not typed. Deep midnight-navy ground with subtle printed-paper grain and a faint blueprint grid ghosted behind the art; luminous cyan linework, warm-cream highlights, a single warm-amber glow accent. Spare, atmospheric, sophisticated — a beautiful magazine science spread, not busy. KEEP the geometry + these key labels legible and in place: <strong>[list every heading, label and number]</strong>. Not photorealistic, not a flat vector chart. Subject: <strong>[one-line description of what the diagram shows]</strong>.</p></blockquote><p><strong>Why the label list matters:</strong> this is a museum-grade atlas — the numbers and names must survive the restyle. Always enumerate them in the prompt; if the art garbles one, regenerate rather than ship it.</p><p><strong>Reference-first, not text-only.</strong> Always pass the SVG sketch as the reference image — it carries the layout so the art stays correct while the style goes loose.</p><h2 id="heroes-vs-inline" tabindex="-1">Heroes vs inline <a class="header-anchor" href="#heroes-vs-inline" aria-label="Permalink to &quot;Heroes vs inline&quot;">​</a></h2><ul><li><strong>Diagram-hero</strong> (e.g. delta-v&#39;s mass-budget bar) — generate like any diagram.</li><li><strong>Photo figures</strong> — reuse vetted <code>missions/&lt;id&gt;/NN</code> or <code>fleet-galleries/…</code> imagery (no generation), honest mission-level captions + credit. Don&#39;t newly source.</li><li><strong>Bespoke photo-hero</strong> — a single text-to-image piece with NO reference sketch and NO text in the image (see Navigation&#39;s lone-craft hero).</li></ul><h2 id="reusing-for-science" tabindex="-1">Reusing for /science <a class="header-anchor" href="#reusing-for-science" aria-label="Permalink to &quot;Reusing for /science&quot;">​</a></h2><p>Same prompt, same palette, same pipeline. A <code>/science</code> concept diagram is authored as an SVG sketch (the section&#39;s key figure), then run through this style so the essays and the science overlays share one visual language.</p>',17)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
